export declare const typeDefs = "\n\t# Tipo User b\u00E1sico (para relaciones con Post)\n\ttype User {\n\t\tid: ID!\n\t\tusername: String!\n\t\tphoto_url: String\n\t}\n\n\t# Tipo para contar likes y comentarios\n\ttype PostCount {\n\t\tcomments: Int!\n\t\tlikes: Int!\n\t}\n\n\t# Tipo Post principal\n\ttype Post {\n\t\tid: ID!\n\t\tuser_id: ID!\n\t\ttype: String!\n\t\tcontent: String\n\t\tmedia_url: String\n\t\tcreated_at: String\n\t\tupdated_at: String\n\t\tuser: User\n\t\tlikesCount: Int\n\t\tcommentsCount: Int\n\t\tsavedCount: Int\n\t\tis_liked: Boolean\n\t\t# Campos de recipe (si el post es de tipo recipe)\n\t\tdescription: String\n\t\ttime_required: Int\n\t\tmoney: Float\n\t}\n\n\t# Tipo Place para lugares (bares, restaurantes, etc.)\n\ttype Place {\n\t\tid: ID!\n\t\tname: String!\n\t\taddress: String!\n\t\tdescription: String\n\t\ttags: [String!]!\n\t\trating: Float\n\t\topen: Boolean\n\t\ttype: String\n\t\tlikesCount: Int\n\t\tcommentsCount: Int\n\t\treservationsCount: Int\n\t}\n\n\t# Tipo UserProfile para la pantalla de perfil\n\ttype UserProfile {\n\t\tid: ID!\n\t\tusername: String!\n\t\tphoto_url: String\n\t\tbio: String\n\t\tlocation: String\n\t\tpostsCount: Int!\n\t\tposts: [Post!]!\n\t\tfollowersCount: Int!\n\t\tfollowingCount: Int!\n\t}\n\n\t# Tipo para la respuesta paginada de posts\n\ttype PostsConnection {\n\t\tdata: [Post!]!\n\t\tnext_cursor: String\n\t\thas_more: Boolean!\n\t}\n\n\t# Input para crear un post\n\tinput CreatePostInput {\n\t\tuser_id: ID!\n\t\ttype: String!\n\t\tcontent: String\n\t\tmedia_url: String\n\t}\n\n\t# Input para actualizar un post\n\tinput UpdatePostInput {\n\t\tcontent: String\n\t\tmedia_url: String\n\t}\n\n\t# Tipo base Query (requerido por GraphQL)\n\ttype Query {\n\t\t_empty: String\n\t}\n\n\t# Tipo base Mutation (requerido por GraphQL)\n\ttype Mutation {\n\t\t_empty: String\n\t}\n";
